mapper.select:
SELECT 
FROM gt_investment_compliance_check
WHERE org_id = #{orgId}

    AND check_no LIKE CONCAT('%', #{checkNo}, '%')


    AND investment_id = #{investmentId}


    AND check_type = #{checkType}


    AND check_result = #{checkResult}


    AND check_status = #{checkStatus}


    AND checker LIKE CONCAT('%', #{checker}, '%')


    AND check_date >= #{startDate}


    AND check_date <= #{endDate}

ORDER BY check_date DESC

SELECT 
FROM gt_investment_compliance_check
WHERE check_no = #{checkNo} AND org_id = #{orgId}

SELECT COALESCE(SUM(violation_count), 0)
FROM gt_investment_compliance_check
WHERE org_id = #{orgId}

SELECT COUNT(*)
FROM gt_investment_compliance_check
WHERE check_no = #{checkNo} AND org_id = #{orgId}

    AND check_id != #{excludeId}

SELECT check_id, check_no, investment_id, 'NON_COMPLIANT' as alertType, CONCAT('合规检查不通过，违规数量：', violation_count) as alertMessage, check_date as alertDate FROM gt_investment_compliance_check WHERE check_result = 'NON_COMPLIANT' AND org_id = #{orgId}
UNION ALL
SELECT check_id, check_no, investment_id, 'OVERDUE_ACTION' as alertType, '纠正措施逾期未完成' as alertMessage, action_deadline as alertDate FROM gt_investment_compliance_check WHERE action_deadline < CURDATE() AND action_status != 'COMPLETED' AND org_id = #{orgId}
UNION ALL
SELECT check_id, check_no, investment_id, 'LOW_COMPLIANCE_SCORE' as alertType, CONCAT('合规评分过低：', compliance_score, '分') as alertMessage, check_date as alertDate FROM gt_investment_compliance_check WHERE compliance_score < 60 AND org_id = #{orgId}
